let output = ($input.item.json.output || '').toString();

// 1. Eliminar bloques <think>...</think> si los hubiera
output = output.replace(/<think>[\s\S]*?<\/think>/gi, '');

// 2. Detectar el "thinking" en inglés al inicio y cortarlo
const triggers = [
  'La IP ',
  'He bloqueado ',
  'Se ha bloqueado ',
  'IP bloqueada',
  'Bloqueo completado',
  'Acción completada'
];

let cutIdx = -1;
for (const t of triggers) {
  const idx = output.indexOf(t);
  if (idx !== -1 && (cutIdx === -1 || idx < cutIdx)) {
    cutIdx = idx;
  }
}
if (cutIdx > 0) {
  output = output.substring(cutIdx);
}

// 3. Eliminar repeticiones de frases.
//    Importante: el split solo debe partir cuando "." va seguido de espacio o fin de cadena,
//    NO cuando va seguido de un dígito (ej. dentro de una IP como 185.220.101.50).
const sentences = output.split(/(?<=[.!?])(?=\s|$)/);
const seen = new Set();
const unique = [];
for (const s of sentences) {
  const trimmed = s.trim();
  const key = trimmed.toLowerCase();
  if (key.length < 5) continue;
  if (seen.has(key)) continue;
  seen.add(key);
  unique.push(trimmed);
}
output = unique.join(' ').trim();

// 4. Limpiar autolinks de Markdown que Discord pegaría mal
output = output.replace(/\[([^\]]+)\]\(https?:\/\/[^)]+\)/g, '$1');

// 5. Eliminar prefijos numerados al inicio (ej: "1. La IP..." → "La IP...")
output = output.replace(/^\s*\d+\.\s+/, '');

// 6. fallback de seguridad: si tras limpiar queda vacío, mensaje por defecto
if (!output || output.length < 5) {
  output = 'Acción completada.';
}

return { json: { output } };

